// 1. Create the Store (store.ts)
import { create } from 'zustand';

interface CartState {
  bears: number;
  increase: () => void;
}

// Extremely simple API! No reducers, no providers, no boilerplate.
export const useCartStore = create<CartState>((set) => ({
  bears: 0,
  increase: () => set((state) => ({ bears: state.bears + 1 })),
}));

// 2. Use it in a Client Component
'use client';
import { useCartStore } from './store';

export function BearCounter() {
  // Only this exact component re-renders when 'bears' changes!
  const bears = useCartStore((state) => state.bears);
  const increase = useCartStore((state) => state.increase);

  return <button onClick={increase}>{bears} bears</button>;
}
